+<body>
+  <a class="skip-link" href="#main-content">Skip to main content</a>
+
+  <main id="main-content">
+    <section class="support-card" aria-labelledby="support-title">
+      <p class="eyebrow">Support</p>
+      <h1 id="support-title">Contact our team</h1>
+      <p class="intro">
+        Tell us how to reach you and a support specialist will follow up with the next steps.
+        Fields marked with <span class="required-marker">*</span> are required.
+      </p>
+
+      <form id="support-form" novalidate>
+        <div class="form-field">
+          <label for="full-name">Full name <span class="required-marker" aria-hidden="true">*</span></label>
+          <input
+            type="text"
+            id="full-name"
+            name="fullName"
+            autocomplete="name"
+            required
+            aria-describedby="full-name-error"
+          >
+          <p class="error-message" id="full-name-error" aria-live="polite"></p>
+        </div>
+
+        <div class="form-field">
+          <label for="email">Email address <span class="required-marker" aria-hidden="true">*</span></label>
+          <input
+            type="email"
+            id="email"
+            name="email"
+            autocomplete="email"
+            required
+            aria-describedby="email-error"
+          >
+          <p class="error-message" id="email-error" aria-live="polite"></p>
+        </div>
+
+        <div class="form-field">
+          <label for="phone">Phone number <span class="required-note">(optional)</span></label>
+          <input
+            type="tel"
+            id="phone"
+            name="phone"
+            autocomplete="tel"
+            inputmode="tel"
+            aria-describedby="phone-help phone-error"
+          >
+          <p class="helper-text" id="phone-help">Use a 10-digit number, such as 555-123-4567.</p>
+          <p class="error-message" id="phone-error" aria-live="polite"></p>
+        </div>
+
+        <button type="submit">Submit support request</button>
+        <p class="status-message" id="form-status" aria-live="polite"></p>
+      </form>
+    </section>
+  </main>
+
+  <script>
+    const form = document.querySelector("#support-form");
+    const statusMessage = document.querySelector("#form-status");
+    const fields = [
+      {
+        input: document.querySelector("#full-name"),
+        error: document.querySelector("#full-name-error"),
+        validate(value) {
+          return value.trim() ? "" : "Enter your full name.";
+        }
+      },
+      {
+        input: document.querySelector("#email"),
+        error: document.querySelector("#email-error"),
+        validate(value) {
+          if (!value.trim()) {
+            return "Enter your email address.";
+          }
+
+          return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)
+            ? ""
+            : "Enter an email address in the format name@example.com.";
+        }
+      },
+      {
+        input: document.querySelector("#phone"),
+        error: document.querySelector("#phone-error"),
+        validate(value) {
+          const trimmedValue = value.trim();
+
+          if (!trimmedValue) {
+            return "";
+          }
+
+          return /^\d{3}[-.\s]?\d{3}[-.\s]?\d{4}$/.test(trimmedValue)
+            ? ""
+            : "Enter a 10-digit phone number, such as 555-123-4567.";
+        }
+      }
+    ];
+
+    function setError(field, message) {
+      field.error.textContent = message;
+      field.input.setAttribute("aria-invalid", message ? "true" : "false");
+    }
+
+    function validateForm() {
+      let firstInvalidField = null;
+
+      fields.forEach((field) => {
+        const message = field.validate(field.input.value);
+        setError(field, message);
+
+        if (message && !firstInvalidField) {
+          firstInvalidField = field.input;
+        }
+      });
+
+      return firstInvalidField;
+    }
+
+    fields.forEach((field) => {
+      field.input.addEventListener("input", () => {
+        if (field.input.getAttribute("aria-invalid") === "true") {
+          setError(field, field.validate(field.input.value));
+        }
+      });
+    });
+
+    form.addEventListener("submit", (event) => {
+      event.preventDefault();
+      statusMessage.textContent = "";
+
+      const firstInvalidField = validateForm();
+
+      if (firstInvalidField) {
+        firstInvalidField.focus();
+        return;
+      }
+
+      statusMessage.textContent = "Thanks. Your support request is ready to send.";
+      form.reset();
+      fields.forEach((field) => setError(field, ""));
+    });
+  </script>
+</body>
+</html>
+

